// src/sprites.js
// Crisp 16-bit / 90s Korean MMORPG (바람의 나라 style) 2D Pixel Art Renderer & Sprite Factory
// Directly renders the sprite sheets generated by Codex CLI (assets/sprites/*.png + manifest.json)
// and dynamically composites Nemesis Scars (burn, eyepatch, stitch, shamed), Rank Crowns, and Auras!

export class PixelSpriteBank {
  constructor() {
    this.cache = new Map();
    this.externalSheets = {};
    this.manifest = null;
    this.loaded = false;
  }

  async loadExternalAssets() {
    try {
      const res = await fetch('./assets/sprites/manifest.json');
      if (res.ok) {
        this.manifest = await res.json();
        const names = ['player', 'captains', 'monsters', 'tiles', 'effects'];
        await Promise.all(
          names.map(
            (name) =>
              new Promise((resolve) => {
                const img = new Image();
                img.onload = () => {
                  this.externalSheets[name] = img;
                  resolve();
                };
                img.onerror = () => resolve();
                img.src = `./assets/sprites/${name}.png`;
              })
          )
        );
      }
    } catch (_) {
      // Fallback cleanly to built-in pixel matrix renderer if offline or file protocol
    }
    this.loaded = true;
    this.cache.clear();
  }

  createCanvas(w = 32, h = 32) {
    const c = document.createElement('canvas');
    c.width = w;
    c.height = h;
    const ctx = c.getContext('2d');
    ctx.imageSmoothingEnabled = false;
    return { c, ctx };
  }

  px(ctx, x, y, w, h, color, scale = 2) {
    ctx.fillStyle = color;
    ctx.fillRect(Math.floor(x * scale), Math.floor(y * scale), Math.ceil(w * scale), Math.ceil(h * scale));
  }

  drawFromSheet(ctx, sheetName, entryKey, frameIndex = 0) {
    const sheetImg = this.externalSheets[sheetName];
    const entry = this.manifest?.sheets?.[sheetName]?.entries?.[entryKey];
    if (!sheetImg || !entry || !entry.frames?.length) return false;
    const f = entry.frames[frameIndex % entry.frames.length];
    ctx.drawImage(sheetImg, f.x, f.y, f.width, f.height, 0, 0, 32, 32);
    return true;
  }

  getTile(type, variant = 0) {
    const key = `tile_${type}_${variant}`;
    if (this.cache.has(key)) return this.cache.get(key);

    const { c, ctx } = this.createCanvas(32, 32);
    if (this.drawFromSheet(ctx, 'tiles', type, variant)) {
      this.cache.set(key, c);
      return c;
    }

    const p = (x, y, w, h, col) => this.px(ctx, x, y, w, h, col, 2);
    switch (type) {
      case 'grass': {
        p(0, 0, 16, 16, '#2d5a27');
        p(1, 2, 2, 1, '#3a7032');
        p(9, 5, 3, 1, '#3a7032');
        p(4, 11, 2, 2, '#24491f');
        if (variant % 3 === 1) {
          p(6, 6, 2, 2, '#facc15');
          p(7, 7, 1, 1, '#ef4444');
        }
        break;
      }
      case 'dirt': {
        p(0, 0, 16, 16, '#855836');
        p(2, 3, 3, 2, '#6e472b');
        p(10, 8, 3, 2, '#9a6b44');
        break;
      }
      case 'stone_floor': {
        p(0, 0, 16, 16, '#475569');
        p(0, 0, 16, 1, '#64748b');
        p(0, 8, 16, 1, '#334155');
        break;
      }
      case 'wall': {
        p(0, 0, 16, 16, '#1e293b');
        p(0, 0, 16, 5, '#0f172a');
        p(0, 5, 16, 1, '#94a3b8');
        break;
      }
      case 'haunted_grass': {
        p(0, 0, 16, 16, '#1e2b24');
        p(2, 4, 3, 1, '#2b3d34');
        break;
      }
      case 'fortress_floor': {
        p(0, 0, 16, 16, '#2a1215');
        p(2, 2, 4, 4, '#3b191d');
        break;
      }
      case 'lava': {
        p(0, 0, 16, 16, '#7f1d1d');
        p(2, 2, 12, 12, '#dc2626');
        p(4, 4, 8, 8, '#f97316');
        break;
      }
      case 'water': {
        p(0, 0, 16, 16, '#1d4ed8');
        p(2, 4, 5, 1, '#60a5fa');
        break;
      }
      case 'tree': {
        p(0, 0, 16, 16, '#2d5a27');
        p(6, 11, 4, 5, '#5c3a21');
        p(3, 8, 10, 4, '#14532d');
        p(4, 5, 8, 4, '#166534');
        break;
      }
      case 'shrine': {
        p(0, 0, 16, 16, '#475569');
        p(4, 4, 8, 8, '#0284c7');
        p(6, 5, 4, 6, '#38bdf8');
        break;
      }
      case 'tavern': {
        p(0, 0, 16, 16, '#451a03');
        p(3, 7, 10, 8, '#9a3412');
        p(6, 9, 4, 6, '#fef08a');
        break;
      }
      default:
        p(0, 0, 16, 16, '#334155');
    }

    this.cache.set(key, c);
    return c;
  }

  getPlayerSprite(dir = 'down', frame = 0, isAttacking = false) {
    const key = `player_${dir}_${frame}_${isAttacking ? 1 : 0}`;
    if (this.cache.has(key)) return this.cache.get(key);

    const { c, ctx } = this.createCanvas(32, 32);
    const entryKey = isAttacking ? `attack_${dir}` : dir;
    if (this.drawFromSheet(ctx, 'player', entryKey, frame)) {
      this.cache.set(key, c);
      return c;
    }

    const p = (x, y, w, h, col) => this.px(ctx, x, y, w, h, col, 2);
    const bob = frame % 2 === 1 ? 1 : 0;
    p(4, 14, 8, 2, 'rgba(0,0,0,0.45)');
    p(5, 1 + bob, 6, 3, '#111827');
    p(4, 2 + bob, 8, 1, '#38bdf8');
    p(5, 4 + bob, 6, 3, '#fed7aa');
    p(4, 7 + bob, 8, 5, '#1e3a8a');
    p(12, 6 + bob, 2, 6, '#38bdf8');

    this.cache.set(key, c);
    return c;
  }

  getCaptainSprite(captain, animFrame = 0) {
    const scarKey = (captain.scars || []).join(',');
    const key = `cap_${captain.id}_${captain.tribeId}_${captain.rank}_${captain.dominated ? 'dom' : 'foe'}_${captain.enraged ? 'rag' : 'calm'}_${captain.broken ? 'brk' : 'ok'}_${scarKey}_${animFrame % 4}`;
    if (this.cache.has(key)) return this.cache.get(key);

    const { c, ctx } = this.createCanvas(32, 32);
    const p = (x, y, w, h, col) => this.px(ctx, x, y, w, h, col, 2);
    const bob = animFrame % 2 === 1 ? 1 : 0;

    // 1. Background Aura (Enraged / Dominated / Overlord)
    if (captain.enraged) {
      p(1, 1, 14, 14, 'rgba(239, 68, 68, 0.28)');
    } else if (captain.dominated) {
      p(1, 1, 14, 14, 'rgba(56, 189, 248, 0.28)');
    } else if (captain.rank === 'overlord') {
      p(1, 0, 14, 15, 'rgba(168, 85, 247, 0.28)');
    }

    // 2. Base Tribe Sprite from Codex CLI captains.png (or procedural fallback)
    const drewExternal = this.drawFromSheet(ctx, 'captains', captain.tribeId, animFrame);
    if (!drewExternal) {
      p(3, 14, 10, 2, 'rgba(0,0,0,0.55)');
      p(5, 2 + bob, 6, 4, '#991b1b');
      p(3, 6 + bob, 10, 6, '#450a0a');
    }

    // 3. Dynamic Nemesis Overlays (Rank Crown & Cheated Death / Shame Scars!)
    if (captain.rank === 'overlord' || captain.rank === 'warchief') {
      p(7, 0 + bob, 2, 2, '#facc15');
    }
    if (captain.scars?.includes('burn')) {
      p(5, 2 + bob, 3, 3, 'rgba(249, 115, 22, 0.85)');
    }
    if (captain.scars?.includes('eyepatch')) {
      p(5, 3 + bob, 3, 2, '#0f172a');
    }
    if (captain.scars?.includes('stitch')) {
      p(5, 5 + bob, 6, 1, '#4ade80');
    }
    if (captain.scars?.includes('shamed')) {
      p(7, 2 + bob, 3, 3, '#e0f2fe');
    }

    this.cache.set(key, c);
    return c;
  }

  getMonsterSprite(type, frame = 0) {
    const key = `mon_${type}_${frame % 4}`;
    if (this.cache.has(key)) return this.cache.get(key);

    const { c, ctx } = this.createCanvas(32, 32);
    if (this.drawFromSheet(ctx, 'monsters', type, frame)) {
      this.cache.set(key, c);
      return c;
    }

    const p = (x, y, w, h, col) => this.px(ctx, x, y, w, h, col, 2);
    p(5, 8, 5, 5, '#b45309');
    this.cache.set(key, c);
    return c;
  }

  getEffectSprite(type, frame = 0) {
    const key = `fx_${type}_${frame % 4}`;
    if (this.cache.has(key)) return this.cache.get(key);
    const { c, ctx } = this.createCanvas(32, 32);
    if (this.drawFromSheet(ctx, 'effects', type, frame)) {
      this.cache.set(key, c);
      return c;
    }
    return null;
  }
}
